                    out[cp_cast_int(usize, j)] = c;
                    j = (j + 1);
                } else {
                    if (std.ascii.isLower(c)) {
                        out[cp_cast_int(usize, j)] = std.ascii.toUpper(c);
                        j = (j + 1);
                    } else {
                        out[cp_cast_int(usize, j)] = c;
                        j = (j + 1);
                    }
                }
            }
        }
        return out[0..j];
}
